begin;
create extension if not exists pgtap with schema extensions;
grant usage on schema extensions to cuevo_api,cuevo_worker;
set local search_path=extensions,pg_catalog;
select no_plan();
-- Rollback-only isolation retains immutable observation/XP source links from prior demos.
update app.habit_observations set occurred_at=clock_timestamp()-interval'400 days';
delete from internal.processed_events;
delete from app.learner_signals;delete from app.learner_state_snapshots;
update internal.outbox_events set state='COMPLETED',completed_at=clock_timestamp(),lease_token=null,lease_until=null where state<>'COMPLETED';
delete from app.current_results;delete from app.current_rubric_results;
insert into app.entitlements(school_id,code,enabled,effective_from)select id,'learner.state',true,'2026-09-01'from app.schools on conflict(school_id,code)do update set enabled=true;
insert into app.learner_state_policies(school_id,development_window_days,version,approved_by)values('10000000-0000-4000-8000-000000000001',14,1,'20000000-0000-4000-8000-000000000002')on conflict(school_id)do nothing;
select ok(to_regclass('app.learner_state_snapshots')is not null,'five dimensional learner state persists');
select ok(to_regclass('app.habit_observations')is not null,'observations separate academic result');
select ok(to_regclass('internal.processed_events')is not null,'processed delivery dedup persists');
select ok(to_regprocedure('internal.process_learner_event(uuid,uuid)')is not null,'private worker processing boundary exists');
create or replace function internal.complete_outbox(event_id uuid,current_lease uuid)returns boolean language sql security definer set search_path=''as'select false';
insert into internal.outbox_events(school_id,id,actor_id,type,entity_type,entity_id,version,metadata,deduplication_key,state,lease_token,lease_until)values('10000000-0000-4000-8000-000000000001','85000000-0000-4000-8000-000000000099','20000000-0000-4000-8000-000000000004','course.create','course','50000000-0000-4000-8000-000000000099',1,'{}','ack-failure','PROCESSING','86000000-0000-4000-8000-000000000099',clock_timestamp()+interval'30 seconds');
set local role cuevo_worker;
select throws_ok($$select internal.process_learner_event('85000000-0000-4000-8000-000000000099','86000000-0000-4000-8000-000000000099')$$,'22023',null,'failed final acknowledgement rolls back processing');
reset role;
select is((select count(*)from internal.processed_events where event_id='85000000-0000-4000-8000-000000000099'),0::bigint,'failed ack no processed marker');
create or replace function internal.complete_outbox(event_id uuid,current_lease uuid)returns boolean language plpgsql security definer set search_path=''as $$declare affected integer;begin update internal.outbox_events set state='COMPLETED',completed_at=clock_timestamp(),lease_token=null,lease_until=null where id=event_id and state='PROCESSING'and lease_token=current_lease and lease_until>clock_timestamp();get diagnostics affected=row_count;return affected=1;end$$;
delete from internal.outbox_events where id='85000000-0000-4000-8000-000000000099';
insert into app.courses(school_id,id,class_id,subject_id,created_by,title,description,status)values('10000000-0000-4000-8000-000000000001','80000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001','43000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000004','Worker synthetic','School authored','PUBLISHED');
insert into app.units(school_id,id,course_id,title,sequence)values('10000000-0000-4000-8000-000000000001','81000000-0000-4000-8000-000000000001','80000000-0000-4000-8000-000000000001','Worker unit',1);
insert into app.lessons(school_id,id,unit_id,title,sequence,body)values('10000000-0000-4000-8000-000000000001','82000000-0000-4000-8000-000000000001','81000000-0000-4000-8000-000000000001','Worker lesson',1,'Synthetic');
insert into app.activities(school_id,id,lesson_id,title,kind,instructions,sequence)values('10000000-0000-4000-8000-000000000001','83000000-0000-4000-8000-000000000001','82000000-0000-4000-8000-000000000001','Practice','practice','Synthetic',1);
insert into app.activity_completions(school_id,id,activity_id,learner_id)values('10000000-0000-4000-8000-000000000001','84000000-0000-4000-8000-000000000001','83000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000012');
insert into app.activities(school_id,id,lesson_id,title,kind,instructions,sequence)values('10000000-0000-4000-8000-000000000001','83000000-0000-4000-8000-000000000002','82000000-0000-4000-8000-000000000001','Unprocessed','reading','Synthetic',2);
insert into app.activity_completions(school_id,id,activity_id,learner_id)values('10000000-0000-4000-8000-000000000001','84000000-0000-4000-8000-000000000002','83000000-0000-4000-8000-000000000002','20000000-0000-4000-8000-000000000012');
insert into internal.outbox_events(school_id,id,actor_id,type,entity_type,entity_id,version,metadata,deduplication_key)values('10000000-0000-4000-8000-000000000001','85000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000012','activity.complete','activity','84000000-0000-4000-8000-000000000001',1,'{"learnerId":"forged"}','worker-golden');
create temporary table worker_lease(id uuid,lease_token uuid);grant select,insert,update,delete on worker_lease to cuevo_worker;
set local role cuevo_worker;
insert into worker_lease select id,lease_token from internal.claim_outbox(1,30);
select throws_ok($$select internal.process_learner_event((select id from worker_lease),'99999999-0000-4000-8000-000000000001')$$,'22023',null,'wrong lease cannot process source');
select lives_ok($$select internal.process_learner_event((select id from worker_lease),(select lease_token from worker_lease))$$,'claimed source completion processed');
select throws_ok($$select internal.process_learner_event((select id from worker_lease),(select lease_token from worker_lease))$$,'22023',null,'completed lease replay cannot repeat processing');
select throws_ok('select *from app.learner_state_snapshots','42501',null,'worker has no raw learner state read');
reset role;
select is((select count(*)from app.habit_observations where source_object_id='84000000-0000-4000-8000-000000000001'),1::bigint,'one source observation');
select is((select development->'practice'->>'count'from app.learner_state_snapshots where school_id='10000000-0000-4000-8000-000000000001'and learner_id='20000000-0000-4000-8000-000000000012'),'1','practice count factual and separate');
select is((select development->'revision'->'count'from app.learner_state_snapshots where school_id='10000000-0000-4000-8000-000000000001'and learner_id='20000000-0000-4000-8000-000000000012'),'null'::jsonb,'revision without approvedsource unknown');
select is((select engagement->>'completedActivityCount'from app.learner_state_snapshots where school_id='10000000-0000-4000-8000-000000000001'and learner_id='20000000-0000-4000-8000-000000000012'),'1','unprocessedcompletion cannot appear without source event provenance');
select ok((select expires_at>clock_timestamp()from app.learner_signals where school_id='10000000-0000-4000-8000-000000000001'and learner_id='20000000-0000-4000-8000-000000000012'),'practice signal has finite source window expiry');
insert into internal.outbox_events(school_id,id,actor_id,type,entity_type,entity_id,version,metadata,deduplication_key)values('10000000-0000-4000-8000-000000000001','85000000-0000-4000-8000-000000000002','20000000-0000-4000-8000-000000000012','activity.complete','activity','84000000-0000-4000-8000-000000000001',1,'{}','worker-duplicate');
update internal.outbox_events set state='PROCESSING',lease_token='86000000-0000-4000-8000-000000000002',lease_until=clock_timestamp()+interval'30 seconds'where id='85000000-0000-4000-8000-000000000002';
set local role cuevo_worker;
select lives_ok($$select internal.process_learner_event('85000000-0000-4000-8000-000000000002','86000000-0000-4000-8000-000000000002')$$,'different event same source idempotent');
reset role;
select is((select count(*)from app.habit_observations where source_object_id='84000000-0000-4000-8000-000000000001'),1::bigint,'duplicateevent no extra habit');
select is((select version from app.learner_state_snapshots where school_id='10000000-0000-4000-8000-000000000001'and learner_id='20000000-0000-4000-8000-000000000012'),1,'duplicate source no duplicate snapshotversion');
update app.learner_state_policies set version=2 where school_id='10000000-0000-4000-8000-000000000001';
insert into internal.outbox_events(school_id,id,actor_id,type,entity_type,entity_id,version,metadata,deduplication_key,state,lease_token,lease_until)values('10000000-0000-4000-8000-000000000001','85000000-0000-4000-8000-000000000004','20000000-0000-4000-8000-000000000012','activity.complete','activity','84000000-0000-4000-8000-000000000002',1,'{}','second-completion','PROCESSING','86000000-0000-4000-8000-000000000004',clock_timestamp()+interval'30 seconds');
set local role cuevo_worker;
select lives_ok($$select internal.process_learner_event('85000000-0000-4000-8000-000000000004','86000000-0000-4000-8000-000000000004')$$,'new completion refreshes approved window context');
reset role;
select is((select rule_version from app.learner_signals where school_id='10000000-0000-4000-8000-000000000001'and learner_id='20000000-0000-4000-8000-000000000012'),2,'signal follows current approved rule version');
insert into internal.outbox_events(school_id,id,actor_id,type,entity_type,entity_id,version,metadata,deduplication_key,state,lease_token,lease_until)values('10000000-0000-4000-8000-000000000002','85000000-0000-4000-8000-000000000003','20000000-0000-4000-8000-000000000133','activity.complete','activity','84000000-0000-4000-8000-000000000001',1,'{}','cross-source','PROCESSING','86000000-0000-4000-8000-000000000003',clock_timestamp()+interval'30 seconds');
set local role cuevo_worker;
select throws_ok($$select internal.process_learner_event('85000000-0000-4000-8000-000000000003','86000000-0000-4000-8000-000000000003')$$,'22023',null,'cross school source mismatch denied');
reset role;
select is((select count(*)from internal.processed_events where event_id='85000000-0000-4000-8000-000000000003'),0::bigint,'invalid source leaves no processed marker');
set local role cuevo_api;select set_config('app.actor_id','20000000-0000-4000-8000-000000000012',true);select set_config('app.school_id','10000000-0000-4000-8000-000000000001',true);
select is(internal.read_current_learner_projection('20000000-0000-4000-8000-000000000012')->>'status','READY','student sees own source-authorized state');
select throws_ok('select*from app.learner_state_snapshots','42501',null,'student cannot bypass source-authorized state through cached JSON');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000013',true);select throws_ok($$select internal.read_current_learner_projection('20000000-0000-4000-8000-000000000012')$$,'42501',null,'peer denied source-authorized state');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000072',true);select is((select count(*)from app.habit_observations),0::bigint,'parent excluded rawhabit');
reset role;
select *from finish();rollback;
